    NormativeSpectrumScore = apps.get_model("polls", "NormativeSpectrumScore")
    QuestionnaireSubmission = apps.get_model("polls", "QuestionnaireSubmission")

    participant_ids = list(
        NormativeParticipant.objects.order_by("pk").values_list("pk", flat=True)
    )
    if not participant_ids and not (
        NormativeScaleScore.objects.exists()
        or NormativeSpectrumScore.objects.exists()
    ):
        return

    migrated_at = timezone.now()
    version = NormativeDatasetVersion.objects.create(
        name="v1",
        status="active",
        prepared_at=migrated_at,
        activated_at=migrated_at,
    )
    NormativeDatasetMembership.objects.bulk_create(
        [
            NormativeDatasetMembership(
                version_id=version.pk,
                participant_id=participant_id,
            )
            for participant_id in participant_ids
        ]
    )
    NormativeScaleScore.objects.update(version_id=version.pk)
    NormativeSpectrumScore.objects.update(version_id=version.pk)
    # Reports were calculated on demand before versioning, so there is no
    # historical report row to migrate. Completed submissions are the safe
    # approximation of reports that may already have been produced with this
    # exact legacy distribution.
    QuestionnaireSubmission.objects.filter(completed=True).update(
        report_normative_version_id=version.pk
    )


